-- (가) SQL Server
SELECT TOP 5 * FROM EMP ORDER BY SAL ASC;

-- (나) SQL Server
SELECT TOP 5 WITH TIES * FROM EMP ORDER BY SAL ASC;

-- (다) Oracle
SELECT * FROM EMP WHERE ROWNUM <= 5 ORDER BY SAL ASC;

-- (라) 표준 SQL
SELECT * FROM EMP ORDER BY SAL ASC FETCH FIRST 5 ROWS ONLY;

SELECT COUNT(*)
FROM T
WHERE 값 NOT BETWEEN 100 AND 200;

-- (가)
SELECT * FROM T1 NATURAL JOIN T2;

-- (나)
SELECT * FROM T1 JOIN T2 USING (ID);

-- (다)
SELECT * FROM T1 CROSS JOIN T2;

-- (라)
SELECT * FROM T1 JOIN T2
ON T1.ID = T2.ID AND T1.TYPE = T2.TYPE;

-- (가)
SELECT C.고객번호 FROM 고객 C
WHERE C.고객번호 NOT IN (
SELECT O.고객번호 FROM 주문 O
WHERE O.고객번호 IS NOT NULL
);

-- (나)
SELECT C.고객번호 FROM 고객 C
WHERE C.고객번호 NOT IN (
SELECT NVL(O.고객번호, 9999) FROM 주문 O
);

-- (다)
SELECT C.고객번호 FROM 고객 C
WHERE EXISTS (
SELECT 1 FROM 주문 O
WHERE C.고객번호 <> O.고객번호
);

-- (라)
SELECT C.고객번호 FROM 고객 C
WHERE NOT EXISTS (
SELECT 1 FROM 주문 O
WHERE C.고객번호 = O.고객번호
);

-- (가)
SELECT DNAME
FROM DEPT;

-- (나)
SELECT b.DEPTNO
FROM (
SELECT b.DEPTNO
FROM DEPT b
) a;

-- (다)
SELECT SUBSTR(DNAME, 1, 3)
FROM DEPT;

-- (라)
SELECT RTRIM(DNAME)
FROM DEPT;

SELECT ENAME
FROM EMP
WHERE ENAME LIKE '%N';

SELECT ID
FROM T
WHERE ROWNUM <> 3;

SELECT *
FROM TBL1 RIGHT OUTER JOIN TBL2 USING ( ㄱ )
WHERE COLC >= 20;

SELECT *
FROM T
WHERE NOT (COL1 = 1 OR COL2 IS NULL);

SELECT COUNT(*)
FROM TAB A, TAB B
WHERE A.COL1 <= B.COL1;

INSERT INTO TAB1 VALUES (4);
SAVEPOINT S1;
INSERT INTO TAB1 VALUES (5);
COMMIT;
INSERT INTO TAB1 VALUES (6);
ROLLBACK TO S1;

SELECT COUNT(*) FROM TAB1;

CREATE TABLE DEPT (
DEPTNO NUMBER PRIMARY KEY
);

CREATE TABLE EMP (
EMPNO  NUMBER CONSTRAINT EMP_PK PRIMARY KEY,
DEPTNO NUMBER CONSTRAINT EMP_FK REFERENCES DEPT(DEPTNO)
);

GRANT SELECT, INSERT ON T TO STAFF;
GRANT DELETE, UPDATE ON T TO MGR;
GRANT STAFF TO MGR;
GRANT MGR TO CHULSU;
GRANT STAFF TO YOUNGHEE;

REVOKE INSERT ON T FROM STAFF;
